def feature(neighbor_colors, adjacency, degree, color_sizes):
    """DSATUR saturation: number of distinct colours among a candidate's coloured neighbours, d = (neighbor_colors > 0).sum(axis=1), normalised by the number of colours used so far c; zeros when c == 0."""
