def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Degree of each candidate, normalised by the maximum degree among candidates (0 if all zero)."""
    degree = np.asarray(degree, dtype=float)
    dmax = degree.max() if degree.size > 0 else 0.0
    if dmax <= 0:
        return np.zeros(degree.shape, dtype=float)
    return degree / dmax

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Largest existing colour class the candidate can join without conflict, divided by n."""
    k = neighbor_colors.shape[0]
    n = k + int(color_sizes.sum())
    if neighbor_colors.shape[1] == 0 or n == 0:
        return np.zeros(k)
    masked = np.where(neighbor_colors == 0, color_sizes[None, :], 0)
    best = masked.max(axis=1)
    return best / n

