def feature(neighbor_colors, adjacency, degree, color_sizes):
    """For each candidate, the fraction of its uncoloured neighbours that have strictly fewer legal colour options than it does (relative local flexibility)."""
    k, c = neighbor_colors.shape
    if k == 0:
        return np.zeros(0)
    if c == 0:
        return np.zeros(k)
    avail = (neighbor_colors == 0).sum(axis=1).astype(float)  # legal options per candidate
    # count neighbours (in restricted graph) with strictly fewer options
    less = (avail[:, None] > avail[None, :]) & adjacency
    cnt = less.sum(axis=1).astype(float)
    uncol_deg = adjacency.sum(axis=1).astype(float)
    out = np.divide(cnt, np.maximum(uncol_deg, 1.0), out=np.zeros(k), where=uncol_deg > 0)
    return np.clip(out, 0.0, 1.0)

