def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Sum over used colours of (colour class size / n), i.e. class-size-weighted saturation."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    n = k + color_sizes.sum()
    used = (neighbor_colors > 0).astype(float)
    w = color_sizes.astype(float) / max(n, 1)
    return (used * w).sum(axis=1)

