def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Fraction of uncoloured neighbours that would take the same colour as this candidate."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    avail = (neighbor_colors == 0)
    has = avail.any(axis=1)
    first = np.argmax(avail, axis=1)
    col = np.where(has, first, c)
    same = (col[:, None] == col[None, :]).astype(float)
    contested = (same * adjacency).sum(axis=1)
    return contested / max(k - 1, 1)

