def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Negative (normalised) size of the smallest existing colour class a candidate can legally join; 0 if none."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    avail = (neighbor_colors == 0)
    sizes = color_sizes.astype(float)
    big = np.where(avail, sizes[None, :], np.inf)
    ms = big.min(axis=1)
    ms = np.where(np.isfinite(ms), ms, 0.0)
    n = k + color_sizes.sum()
    return -ms / max(n, 1)

