def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Fraction of currently used colours visible within two hops (direct coloured neighbours plus colours used by coloured neighbours of the candidate's uncoloured neighbours)."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    blocked = (neighbor_colors > 0).astype(float)          # (k, c)
    two = adjacency.astype(float) @ blocked                # (k, c)
    seen = (blocked > 0) | (two > 0)
    return seen.sum(axis=1) / c

