def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Normalised degree times the fraction of used colours present among a candidate's coloured neighbours."""
    k = degree.shape[0]
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    deg_norm = degree / max(float(degree.max()), 1.0)
    sat = (neighbor_colors > 0).sum(axis=1) / c
    return deg_norm * sat

