def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Relative damage: for each candidate, the average over its available colours of the neighbour option-losses it would cause, each weighted by 1/(that neighbour's own option count)."""
    k, c = neighbor_colors.shape
    if c == 0 or k < 2:
        return np.zeros(k)
    avail = (neighbor_colors == 0).astype(float)          # (k, c) colours a candidate could take
    ac = np.maximum(avail.sum(axis=1), 1.0)               # each candidate's own option count
    per_neigh = avail / ac[:, None]                       # (k, c) relative loss per colour
    P = adjacency.astype(float) @ per_neigh               # (k, c) summed relative loss over neighbours
    damage = (avail * P).sum(axis=1) / c                  # average over available colours
    return damage / max(k - 1, 1.0)

