def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Mean size of joinable colour classes weighted by how close each is to being full (n - size)."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    avail = (neighbor_colors == 0).astype(float)
    sizes = color_sizes.astype(float)
    n = k + sizes.sum()
    # weight each joinable class by its remaining room (n - size), so large-but-crowded
    # classes count less than large-and-open ones; normalise by c * n^2 to stay in [0,1].
    room = np.maximum(n - sizes, 0.0)
    return (avail @ (sizes * room)) / (c * max(n * n, 1.0))

