def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Size of the colour class a candidate would take minus the average class size, 0 if it opens a new colour."""
    k, c = neighbor_colors.shape
    n = k + int(color_sizes.sum())
    if c == 0:
        return np.zeros(k)
    free = (neighbor_colors == 0)
    has_free = free.any(axis=1)
    t = np.where(has_free, free.argmax(axis=1), 0)
    avg = 1.0 / (c + 1)
    sz = np.where(has_free, color_sizes[t] / max(n, 1), 0.0)
    return np.where(has_free, sz - avg, 0.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """For each candidate: the size of the smallest colour class it could legally join, normalised by the number of coloured vertices (0 if it must open a new colour)."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    n_colored = float(color_sizes.sum())
    if n_colored <= 0:
        return np.zeros(k)
    sizes = color_sizes.astype(float)
    # option mask: colour j is legally available to candidate i iff no neighbour uses it
    avail = (neighbor_colors == 0)  # (k, c)
    big = np.where(avail, sizes[None, :], np.inf)
    min_size = big.min(axis=1)  # inf if no option -> must open a new colour
    min_size = np.where(np.isfinite(min_size), min_size, 0.0)
    return np.clip(min_size / n_colored, 0.0, 1.0)
